//! 🪦️ Actual Source retirement can close its producer while retaining an unloaned history root.
use semio_framework_job_context::{Generation,OperationId,OriginalNativeRetirement,OriginalTurnFailure,RetainedCloneGrant,StepContext};
use semio_framework_job_testing_caller::OriginalJobFixtureCaller;
static CLOSES:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);
struct Leaf{closed:bool,visits:usize}
impl OriginalNativeRetirement for Leaf{fn close_on_source(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if cx.retirement_should_yield(){return Ok(false)}cx.consume_retained(semio_framework_job_context::RetainedCloneProgress{copied_items:1,copied_bytes:std::mem::size_of::<bool>(),..Default::default()})?;cx.consume_fuel(1);self.closed=true;CLOSES.fetch_add(1,std::sync::atomic::Ordering::Relaxed);Ok(true)}fn terminal_is_empty(&self)->bool{self.closed}}
impl Drop for Leaf{fn drop(&mut self){assert!(std::thread::panicking()||self.closed)}}
fn clock()->Option<u64>{Some(1)}
#[test]
fn producer_target_and_retained_root_keep_actual_source_custody(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let grant=RetainedCloneGrant{maximum_items:65536,maximum_copy_bytes:16777216,maximum_capacity_bytes:16777216,maximum_release_bytes:16777216,maximum_depth:128};let mut caller=OriginalJobFixtureCaller::admit(OperationId(720),Generation(1),grant,clock,1000000,1000000);caller.admit_return_table();let mut foreign=OriginalJobFixtureCaller::admit(OperationId(721),Generation(1),grant,clock,1000000,1000000);
 for _ in 0..64{if caller.refreshed_turn(grant,|cx|cx.admit_original_return_table()).unwrap(){break}}
 let(mut history,mut producer)=(None,None);let mut input=Some(Leaf{closed:false,visits:0});assert!(caller.refreshed_turn(grant,|cx|cx.admit_original_native(&mut input,&mut history)).unwrap());let mut input=Some(Leaf{closed:false,visits:0});assert!(caller.refreshed_turn(grant,|cx|cx.admit_original_native(&mut input,&mut producer)).unwrap());let h=history.as_ref().unwrap().recipient_identity();let p=producer.as_ref().unwrap().recipient_identity();
 assert_eq!(foreign.refreshed_turn(grant,|cx|cx.close_original_native_recipient_step(p)).is_err(),law["foreignRefused"].as_bool().unwrap());assert_eq!(caller.refreshed_turn(grant,|cx|cx.with_original_native_root_step::<Leaf>(h,|_,_|panic!("live child must prevent root visit"))).unwrap(),law["liveVisit"].as_bool().unwrap());drop(history);drop(producer);
 let mut complete=false;let mut denied_release=false;for _ in 0..512{let(result,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||caller.refreshed_turn(grant,|cx|cx.close_original_native_recipient_step(p)));assert_eq!(heap,(caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes));if result.unwrap(){complete=true;break}if CLOSES.load(std::sync::atomic::Ordering::Relaxed)==1&&!denied_release{let denied=RetainedCloneGrant{maximum_copy_bytes:0,..grant};let(result,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||caller.refreshed_turn(denied,|cx|cx.close_original_native_recipient_step(p)));assert_eq!(result.unwrap(),law["physicalMetadata"]["zeroCopyRelease"].as_bool().unwrap());assert_eq!(heap,(0,0));assert_eq!(caller.business_receipt(),Default::default());denied_release=true;}}assert_eq!(complete,law["producerClosed"].as_bool().unwrap());assert!(denied_release);
 let proof=caller.refreshed_turn(grant,|cx|{let proof=cx.original_native_retired_witness(p)?;Ok(proof.is_some_and(|proof|proof.proves(p,cx)))}).unwrap();assert_eq!(proof,law["globalWitness"].as_bool().unwrap());
 let mut visited=false;assert!(caller.refreshed_turn(grant,|cx|cx.with_original_native_root_step::<Leaf>(h,|leaf,cx|{assert_eq!(leaf.closed,law["historyClosedBefore"].as_bool().unwrap());cx.consume_retained(semio_framework_job_context::RetainedCloneProgress{copied_items:1,copied_bytes:std::mem::size_of::<usize>(),..Default::default()})?;cx.consume_fuel(1);leaf.visits+=1;visited=true;Ok(())})).unwrap());assert_eq!(visited,law["historyVisited"].as_bool().unwrap());assert_eq!(caller.refreshed_turn(grant,|cx|cx.with_original_native_root_step::<Leaf>(p,|_,_|panic!("closed root must refuse"))).is_err(),law["closedVisitRefused"].as_bool().unwrap());
 let mut input=Some(Leaf{closed:false,visits:0});let mut replacement=None;assert!(caller.refreshed_turn(grant,|cx|cx.admit_original_native(&mut input,&mut replacement)).unwrap());assert!(caller.refreshed_turn(grant,|cx|cx.close_original_native_recipient_step(p)).unwrap());let mut live=false;assert!(caller.refreshed_turn(grant,|cx|replacement.as_mut().unwrap().with_native(cx,|leaf,_|{live=!leaf.closed;Ok(())})).unwrap());assert_eq!(live,law["reusedSiblingLive"].as_bool().unwrap());drop(replacement);
 for _ in 0..512{if caller.refreshed_turn(grant,|cx|cx.close_original_native_step()).unwrap(){break}}caller.retire(grant);foreign.retire(grant);
}
